    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + (x + 6) + x + 7</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + 6 + x + 7</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 3 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 13"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 3 x + 13</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 3 × <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 13</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">3 × <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> = <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span></span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + 13 = <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">2</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">3 x + 13 = 25</span>"},{"quoi":"نطرح 13 من الطرفين","math":"<span dir=\"ltr\" class=\"expr\">3 x = 25 - 13</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">25 - 13 = 12</span>"},{"quoi":"نقسم على 3","math":"<span dir=\"ltr\" class=\"expr\">x = 12 : 3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 4</span>"}],
