    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 6 + (x + 4)</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + x + 6 + x + 4</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 4 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 10"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 x + 10</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نعوّض في العبارة","math":"<span dir=\"ltr\" class=\"expr\">P = 4 × <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + 10</span>"},{"quoi":"نحسب الجداء","math":"<span dir=\"ltr\" class=\"expr\">4 × <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> = <span class=\"frac\"><span class=\"num\">28</span><span class=\"den\">3</span></span></span>"},{"quoi":"نجمع","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">28</span><span class=\"den\">3</span></span> + 10 = <span class=\"frac\"><span class=\"num\">58</span><span class=\"den\">3</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = <span class=\"frac\"><span class=\"num\">58</span><span class=\"den\">3</span></span></span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">4 x + 10 = 46</span>"},{"quoi":"نطرح 10 من الطرفين","math":"<span dir=\"ltr\" class=\"expr\">4 x = 46 - 10</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">46 - 10 = 36</span>"},{"quoi":"نقسم على 4","math":"<span dir=\"ltr\" class=\"expr\">x = 36 : 4</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 9</span>"}],
