    enonce: "<span class=\"q\">1) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span> و <span dir=\"ltr\" class=\"expr\">ab = 216</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 4(8a + 9b) - 4(a + 5b)</span> ثمّ جد قيمتها العددية<br><span class=\"q\">2) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span> و <span dir=\"ltr\" class=\"expr\">ab = 216</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 4(8a + 9b) - 4(a + 5b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 21a + 12b + 27</span> ثمّ جد قيمتها العددية<br><span class=\"q\">3) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span> و <span dir=\"ltr\" class=\"expr\">ab = 216</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 4(8a + 9b) - 4(a + 5b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 21a + 12b + 27</span> احسب القيمة العددية للعبارة <span dir=\"ltr\" class=\"expr\">G = (a + 4)(b + 7)</span><br><span class=\"q\">4) </span>a و b عددان طبيعيان يحقّقان <span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span> و <span dir=\"ltr\" class=\"expr\">ab = 216</span> أنشر و اختصر العبارة <span dir=\"ltr\" class=\"expr\">E = 4(8a + 9b) - 4(a + 5b)</span> فكّك إلى جداء عوامل العبارة <span dir=\"ltr\" class=\"expr\">F = 21a + 12b + 27</span> احسب القيمة العددية للعبارة جد العددين a و b علما أنّ الفرق بينهما يساوي 6",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">4(8a + 9b) - 4(a + 5b) = 32a + 36b - 4a - 20b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">32a + 36b - 4a - 20b = 32a - 4a + 36b - 20b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">32a + 36b - 4a - 20b = 28a + 16b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">28a + 16b = 4(7a + 4b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">4(7a + 4b) = 4 × 174</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 696</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 21 و 12 و 27 كلّها مضاعفات لـ 3"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">21a + 12b + 27 = 3(7a + 4b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">174 + 9 = 183</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">3 × 183 = 549</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 549</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 4)(b + 7) = ab + 7a + 4b + 28</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 216</span> و <span dir=\"ltr\" class=\"expr\">7a + 4b = 174</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 7a + 4b + 28 = 216 + 174 + 28</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">216 + 174 + 28 = 418</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 418</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 6</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 6</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">7(b + 6) + 4b = 174</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">7b + 42 + 4b = 174</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">11b + 42 = 174</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">11b = 174 - 42</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 132 : 11 = 12</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 6 = 18</span>"}],
