    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">2(9a + 7b) - 2(a + 5b) = 18a + 14b - 2a - 10b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">18a + 14b - 2a - 10b = 18a - 2a + 14b - 10b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">18a + 14b - 2a - 10b = 16a + 4b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">16a + 4b = 2(8a + 2b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">2(8a + 2b) = 2 × 86</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 172</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 16 و 4 و 8 كلّها مضاعفات لـ 2"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">16a + 4b + 8 = 2(8a + 2b + 4)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">8a + 2b = 86</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">86 + 4 = 90</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">2 × 90 = 180</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 180</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 2)(b + 8) = ab + 8a + 2b + 16</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 63</span> و <span dir=\"ltr\" class=\"expr\">8a + 2b = 86</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 8a + 2b + 16 = 63 + 86 + 16</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">63 + 86 + 16 = 165</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 165</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 2</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 2</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">8(b + 2) + 2b = 86</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">8b + 16 + 2b = 86</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">10b + 16 = 86</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">10b = 86 - 16</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 70 : 10 = 7</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 2 = 9</span>"}],
