    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"ننشر القوسين","math":"<span dir=\"ltr\" class=\"expr\">4(5a + 8b) - 5(a + 1b) = 20a + 32b - 5a - 5b</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">20a + 32b - 5a - 5b = 20a - 5a + 32b - 5b</span>"},{"quoi":"نختصر","math":"<span dir=\"ltr\" class=\"expr\">20a + 32b - 5a - 5b = 15a + 27b</span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">15a + 27b = 3(5a + 9b)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">3(5a + 9b) = 3 × 108</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = 324</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نبحث عن عامل مشترك","math":"الأعداد 15 و 27 و 27 كلّها مضاعفات لـ 3"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">15a + 27b + 27 = 3(5a + 9b + 9)</span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">5a + 9b = 108</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">108 + 9 = 117</span>"},{"quoi":"نضرب","math":"<span dir=\"ltr\" class=\"expr\">3 × 117 = 351</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">F = 351</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"ننشر جداء القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a + 9)(b + 5) = ab + 5a + 9b + 45</span>"},{"quoi":"نجمع المعطيات","math":"<span dir=\"ltr\" class=\"expr\">ab = 63</span> و <span dir=\"ltr\" class=\"expr\">5a + 9b = 108</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">ab + 5a + 9b + 45 = 63 + 108 + 45</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">63 + 108 + 45 = 216</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">G = 216</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 2</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 2</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">5(b + 2) + 9b = 108</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">5b + 10 + 9b = 108</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">14b + 10 = 108</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">14b = 108 - 10</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 98 : 14 = 7</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 2 = 9</span>"}],
